   128	async function serveStatic(res, staticRoot, pathname) {
   129	  const resolved = resolveStaticPath(staticRoot, pathname);
   130	  if (resolved.statusCode !== undefined) {
   131	    res.writeHead(resolved.statusCode, { 'Content-Type': 'text/plain; charset=utf-8' });
   132	    res.end('Forbidden\n');
   133	    return;
   134	  }
   135	
   136	  let stat;
   137	  try {
   138	    stat = await fs.promises.stat(resolved.filePath);
   139	    if (!stat.isFile()) {
   140	      throw new Error('not a file');
   141	    }
   142	  } catch {
   143	    sendStaticMissing(res);
   144	    return;
   145	  }
   146	
   147	  const contentType = MIME_TYPES.get(path.extname(resolved.filePath).toLowerCase()) ?? 'application/octet-stream';
   148	  res.writeHead(200, {
   149	    'Content-Type': contentType,
   150	    'Content-Length': stat.size,
   151	    'X-Content-Type-Options': 'nosniff',
   152	  });
   153	
   154	  if (res.req !== undefined && res.req.method === 'HEAD') {
   155	    res.end();
   156	    return;
   157	  }
   158	
   159	  const stream = fs.createReadStream(resolved.filePath);
