   171	    const pathname = getRequestPath(req.url ?? '/');
   172	
   173	    if (pathname === '/api/levels' || pathname.startsWith('/api/')) {
   174	      if (pathname !== '/api/levels') {
   175	        sendApiError(res, 404, 'API_NOT_FOUND', '请求的 API 不存在。');
   176	        return;
   177	      }
   178	
   179	      if (!API_METHODS.has(req.method ?? '')) {
   180	        sendApiError(res, 405, 'METHOD_NOT_ALLOWED', '该 API 不支持当前请求方法。');
   181	        return;
