   183	
   184	      try {
   185	        const levels = await loadLevels(dataPath);
   186	        sendJson(res, 200, levels);
   187	      } catch (error) {
   188	        if (error instanceof LevelDataError) {
   189	          sendApiError(res, 500, error.code, error.message);
