   191	        }
   192	        sendApiError(res, 500, 'INTERNAL_SERVER_ERROR', '服务内部错误，请稍后重试。');
   193	      }
   194	      return;
   195	    }
   196	
   197	    if (!STATIC_METHODS.has(req.method ?? '')) {
   198	      sendApiError(res, 405, 'METHOD_NOT_ALLOWED', '该资源不支持当前请求方法。');
   199	      return;
   200	    }
   201	
   202	    await serveStatic(res, staticRoot, pathname);
   203	  };
   204	
   205	  return http.createServer((req, res) => {
   206	    requestHandler(req, res).catch(() => {
