   216	function resolvePort(port) {
   217	  if (port !== undefined) {
   218	    return port;
   219	  }
   220	
   221	  if (process.env.PORT !== undefined && process.env.PORT !== '') {
   222	    return Number(process.env.PORT);
   223	  }
   224	
   225	  return DEFAULT_PORT;
   226	}
