   228	async function start(server = createServer(), { host = DEFAULT_HOST, port } = {}) {
   229	  const listenPort = resolvePort(port);
   230	  if (!Number.isInteger(listenPort) || listenPort < 0 || listenPort > 65535) {
   231	    throw new RangeError('port must be an integer between 0 and 65535');
   232	  }
   233	
   234	  server.listen({ host, port: listenPort });
   235	  await once(server, 'listening');
   236	  const actualPort = server.address().port;
   237	
   238	  return {
   239	    origin: `http://${host}:${actualPort}`,
   240	    port: actualPort,
   241	    async stop() {
   242	      await stop(server);
   243	    },
   244	  };
   245	}
