     5	
     6	async function request(origin, path, { method = 'GET' } = {}) {
     7	  const parsedOrigin = new URL(origin);
     8	  return new Promise((resolve, reject) => {
     9	    const req = http.request(
    10	      {
    11	        agent: false,
    12	        host: parsedOrigin.hostname,
    13	        port: parsedOrigin.port,
    14	        path,
    15	        method,
    16	      },
    17	      (res) => {
    18	      let raw = Buffer.alloc(0);
    19	      res.on('data', (chunk) => {
    20	        raw = Buffer.concat([raw, chunk]);
    21	      });
    22	      res.on('end', () => resolve({ res, body: raw }));
    23	      }
    24	    );
    25	    req.on('error', reject);
    26	    req.end();
    27	  });
    28	}
    29	
    30	async function stopServer(server) {
    31	  server.close();
    32	  await once(server, 'close');
    33	}
    34	
    35	async function startServer(server, { port = 0, host = '127.0.0.1' } = {}) {
    36	  server.listen({ port, host });
    37	  await once(server, 'listening');
    38	  const address = server.address();
    39	  return { port: address.port, origin: `http://${host}:${address.port}` };
    40	}
    41	
    42	module.exports = { request, startServer, stopServer };

