+'use strict';
+
+const fs = require('node:fs');
+const http = require('node:http');
+const path = require('node:path');
+const { once } = require('node:events');
+
+const DEFAULT_HOST = '127.0.0.1';
+const DEFAULT_PORT = 3000;
+const DEFAULT_DATA_PATH = path.resolve(__dirname, '../data/levels.json');
+const DEFAULT_STATIC_ROOT = path.resolve(__dirname, '../web');
+const LEVEL_DIFFICULTIES = new Set(['easy', 'normal', 'hard', 'expert']);
+const API_METHODS = new Set(['GET', 'HEAD']);
+const STATIC_METHODS = new Set(['GET', 'HEAD']);
+
+const MIME_TYPES = new Map([
+  ['.css', 'text/css; charset=utf-8'],
+  ['.html', 'text/html; charset=utf-8'],
+  ['.js', 'text/javascript; charset=utf-8'],
+  ['.json', 'application/json; charset=utf-8'],
+  ['.svg', 'image/svg+xml'],
+  ['.txt', 'text/plain; charset=utf-8'],
+]);
+
+class LevelDataError extends Error {
+  constructor() {
+    super('关卡数据当前不可用，请稍后重试。');
+    this.name = 'LevelDataError';
+    this.code = 'LEVEL_DATA_UNAVAILABLE';
+  }
+}
+
+function sendJson(res, statusCode, payload) {
+  const body = JSON.stringify(payload);
+  res.writeHead(statusCode, {
+    'Content-Type': 'application/json; charset=utf-8',
+    'Content-Length': Buffer.byteLength(body),
+  });
+  res.end(res.req !== undefined && res.req.method === 'HEAD' ? undefined : body);
+}
+
+function sendApiError(res, statusCode, code, message) {
+  sendJson(res, statusCode, { error: { code, message } });
+}
+
+function sendStaticMissing(res) {
+  res.writeHead(404, {
+    'Content-Type': 'text/plain; charset=utf-8',
+    'Content-Length': Buffer.byteLength('Not Found\n'),
+  });
+  res.end(res.req !== undefined && res.req.method === 'HEAD' ? undefined : 'Not Found\n');
+}
+
+function getRequestPath(rawUrl) {
+  return new URL(rawUrl, 'http://127.0.0.1').pathname;
+}
+
+function isPlainObject(value) {
+  return typeof value === 'object' && value !== null && !Array.isArray(value);
+}
+
+function isNonEmptyString(value) {
+  return typeof value === 'string' && value.trim().length > 0;
+}
+
+function validateLevels(value) {
+  if (!Array.isArray(value)) {
+    throw new LevelDataError();
+  }
+
+  for (const level of value) {
+    if (
+      !isPlainObject(level) ||
+      !isNonEmptyString(level.id) ||
+      !isNonEmptyString(level.name) ||
+      !isNonEmptyString(level.map) ||
+      !LEVEL_DIFFICULTIES.has(level.difficulty) ||
+      !isPlainObject(level.position) ||
+      !Number.isFinite(level.position.x) ||
+      !Number.isFinite(level.position.y) ||
+      !Array.isArray(level.enemies) ||
+      !level.enemies.every(isNonEmptyString)
+    ) {
+      throw new LevelDataError();
+    }
+  }
+
+  return value;
+}
+
+async function loadLevels(dataPath) {
+  try {
+    const source = await fs.promises.readFile(dataPath, 'utf8');
+    return validateLevels(JSON.parse(source));
+  } catch (error) {
+    if (error instanceof LevelDataError) {
+      throw error;
+    }
+    throw new LevelDataError();
+  }
+}
+
+function resolveStaticPath(staticRoot, pathname) {
+  let decodedPath;
+  try {
+    decodedPath = decodeURIComponent(pathname);
+  } catch {
+    return { statusCode: 400 };
+  }
+
+  if (decodedPath.includes('\0')) {
+    return { statusCode: 400 };
+  }
+
+  const withoutLeadingSlash = decodedPath.startsWith('/') ? decodedPath.slice(1) : decodedPath;
+  const normalizedRelative = path.posix.normalize(withoutLeadingSlash);
+  const rootDirectory = path.resolve(staticRoot);
+  const candidate = path.resolve(rootDirectory, normalizedRelative);
+  const rootPrefix = `${rootDirectory}${path.sep}`;
+
+  if (candidate !== rootDirectory && !candidate.startsWith(rootPrefix)) {
+    return { statusCode: 403 };
+  }
+
+  return { filePath: candidate === rootDirectory ? path.join(rootDirectory, 'index.html') : candidate };
+}
+
+async function serveStatic(res, staticRoot, pathname) {
+  const resolved = resolveStaticPath(staticRoot, pathname);
+  if (resolved.statusCode !== undefined) {
+    res.writeHead(resolved.statusCode, { 'Content-Type': 'text/plain; charset=utf-8' });
+    res.end('Forbidden\n');
+    return;
+  }
+
+  let stat;
+  try {
+    stat = await fs.promises.stat(resolved.filePath);
+    if (!stat.isFile()) {
+      throw new Error('not a file');
+    }
+  } catch {
+    sendStaticMissing(res);
+    return;
+  }
+
+  const contentType = MIME_TYPES.get(path.extname(resolved.filePath).toLowerCase()) ?? 'application/octet-stream';
+  res.writeHead(200, {
+    'Content-Type': contentType,
+    'Content-Length': stat.size,
+    'X-Content-Type-Options': 'nosniff',
+  });
+
+  if (res.req !== undefined && res.req.method === 'HEAD') {
+    res.end();
+    return;
+  }
+
+  const stream = fs.createReadStream(resolved.filePath);
+  stream.on('error', () => {
+    res.destroy();
+  });
+  stream.pipe(res);
+}
+
+function createServer(options = {}) {
+  const dataPath = options.dataPath ?? DEFAULT_DATA_PATH;
+  const staticRoot = options.staticRoot ?? DEFAULT_STATIC_ROOT;
+
+  const requestHandler = async (req, res) => {
+    const pathname = getRequestPath(req.url ?? '/');
+
+    if (pathname === '/api/levels' || pathname.startsWith('/api/')) {
+      if (pathname !== '/api/levels') {
+        sendApiError(res, 404, 'API_NOT_FOUND', '请求的 API 不存在。');
+        return;
+      }
+
+      if (!API_METHODS.has(req.method ?? '')) {
+        sendApiError(res, 405, 'METHOD_NOT_ALLOWED', '该 API 不支持当前请求方法。');
+        return;
+      }
+
+      try {
+        const levels = await loadLevels(dataPath);
+        sendJson(res, 200, levels);
+      } catch (error) {
+        if (error instanceof LevelDataError) {
+          sendApiError(res, 500, error.code, error.message);
+          return;
+        }
+        sendApiError(res, 500, 'INTERNAL_SERVER_ERROR', '服务内部错误，请稍后重试。');
+      }
+      return;
+    }
+
+    if (!STATIC_METHODS.has(req.method ?? '')) {
+      sendApiError(res, 405, 'METHOD_NOT_ALLOWED', '该资源不支持当前请求方法。');
+      return;
+    }
+
+    await serveStatic(res, staticRoot, pathname);
+  };
+
+  return http.createServer((req, res) => {
+    requestHandler(req, res).catch(() => {
+      if (!res.headersSent) {
+        sendApiError(res, 500, 'INTERNAL_SERVER_ERROR', '服务内部错误，请稍后重试。');
+      } else {
+        res.destroy();
+      }
+    });
+  });
+}
+
+function resolvePort(port) {
+  if (port !== undefined) {
+    return port;
+  }
+
+  if (process.env.PORT !== undefined && process.env.PORT !== '') {
+    return Number(process.env.PORT);
+  }
+
+  return DEFAULT_PORT;
+}
+
+async function start(server = createServer(), { host = DEFAULT_HOST, port } = {}) {
+  const listenPort = resolvePort(port);
+  if (!Number.isInteger(listenPort) || listenPort < 0 || listenPort > 65535) {
+    throw new RangeError('port must be an integer between 0 and 65535');
+  }
+
+  server.listen({ host, port: listenPort });
+  await once(server, 'listening');
+  const actualPort = server.address().port;
+
+  return {
+    origin: `http://${host}:${actualPort}`,
+    port: actualPort,
+    async stop() {
+      await stop(server);
+    },
+  };
+}
+
+async function stop(server) {
+  if (!server.listening) {
+    return;
+  }
+  server.close();
+  await once(server, 'close');
+}
+
+if (require.main === module) {
+  let activeService;
+  let shuttingDown = false;
+
+  const shutdown = async () => {
+    if (shuttingDown) {
+      return;
+    }
+    shuttingDown = true;
+    if (activeService !== undefined) {
+      await activeService.stop().catch(() => undefined);
+    }
+  };
+
+  start()
+    .then((service) => {
+      activeService = service;
+      process.stdout.write(`${service.origin}\n`);
+    })
+    .catch((error) => {
+      process.stderr.write(`${error.message}\n`);
+      process.exitCode = 1;
+    });
+
+  process.once('SIGINT', shutdown);
+  process.once('SIGTERM', shutdown);
+}
+
+module.exports = {
+  DEFAULT_HOST,
+  DEFAULT_PORT,
+  createServer,
+  start,
+  stop,
+};
