+'use strict';
+
+const http = require('node:http');
+const { once } = require('node:events');
+
+async function request(origin, path, { method = 'GET' } = {}) {
+  const parsedOrigin = new URL(origin);
+  return new Promise((resolve, reject) => {
+    const req = http.request(
+      {
+        agent: false,
+        host: parsedOrigin.hostname,
+        port: parsedOrigin.port,
+        path,
+        method,
+      },
+      (res) => {
+      let raw = Buffer.alloc(0);
+      res.on('data', (chunk) => {
+        raw = Buffer.concat([raw, chunk]);
+      });
+      res.on('end', () => resolve({ res, body: raw }));
+      }
+    );
+    req.on('error', reject);
+    req.end();
+  });
+}
+
+async function stopServer(server) {
+  server.close();
+  await once(server, 'close');
+}
+
+async function startServer(server, { port = 0, host = '127.0.0.1' } = {}) {
+  server.listen({ port, host });
+  await once(server, 'listening');
+  const address = server.address();
+  return { port: address.port, origin: `http://${host}:${address.port}` };
+}
+
+module.exports = { request, startServer, stopServer };
