+'use strict';
+
+const { test } = require('node:test');
+const assert = require('node:assert/strict');
+const path = require('node:path');
+
+const { DEFAULT_PORT, createServer, start } = require('../../server/server.js');
+const { request } = require('./helpers.js');
+
+test('start(port 0) 返回实际 origin 与 port，stop 关闭监听', async () => {
+  const server = createServer({ dataPath: path.resolve(__dirname, './fixtures/data/levels.json') });
+  const launched = await start(server, { port: 0 });
+
+  try {
+    assert.equal(launched.port, server.address().port);
+    assert.ok(Number.isInteger(launched.port));
+    assert.ok(launched.port > 0);
+    assert.match(launched.origin, /^http:\/\/127\.0\.0\.1:\d+$/);
+    assert.equal(typeof launched.stop, 'function');
+
+    const { res, body } = await request(launched.origin, '/api/levels');
+    assert.equal(res.statusCode, 200);
+    assert.equal(JSON.parse(body.toString('utf8')).length, 1);
+  } finally {
+    await launched.stop();
+    assert.equal(server.listening, false);
+  }
+});
+
+test('未显式传入 port 时支持 PORT 环境变量并保留默认端口 3000', async () => {
+  assert.equal(DEFAULT_PORT, 3000);
+
+  const previousPort = process.env.PORT;
+  process.env.PORT = '0';
+  const server = createServer({ dataPath: path.resolve(__dirname, './fixtures/data/levels.json') });
+
+  try {
+    const launched = await start(server);
+    try {
+      assert.ok(Number.isInteger(launched.port));
+      assert.notEqual(launched.port, DEFAULT_PORT);
+    } finally {
+      await launched.stop();
+    }
+  } finally {
+    if (previousPort === undefined) {
+      delete process.env.PORT;
+    } else {
+      process.env.PORT = previousPort;
+    }
+  }
+});
